(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025-t*0.15)*8 + Math.cos(sy*0.02+t*0.1)*6;
  const w2y = Math.cos(sy*0.025+t*0.2)*8 + Math.sin(sx*0.015-t*0.12)*6;
  const dx = sx + w2x, dy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*55, 0.075, 1.8, 1.05],
    [200+Math.sin(t*0.38+6)*90, 220+Math.cos(t*0.48+3)*60, 0.095, 2.4, 0.9]
  ];
  let aS = 0, iS = 0, tw = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((dx-sX)**2 + (dy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    tw += w;
  }
  const act = aS/tw, inh = iS/tw;
  const bg1 = (Math.sin(dx*0.04+dy*0.025+t*0.8) + Math.sin(dx*0.03-dy*0.04+t*1.1))/2;
  const bg2 = (Math.sin(dx*0.08-dy*0.06+t*1.5) + Math.cos(dx*0.06+dy*0.07-t*1.3))/2;
  const bg3 = Math.sin((dx+dy)*0.12+t*2.5)*0.2 + Math.sin((dx-dy)*0.1-t*2)*0.2;
  const bg = bg1 + bg2*0.4 + bg3;
  const d1 = Math.sqrt((dx-cx)**2 + (dy-cy)**2), a1 = Math.atan2(dy-cy, dx-cx);
  const sp1 = (Math.sin(d1*0.05-a1*3-t*1.5) + Math.sin(d1*0.04+a1*4-t*1.2))*0.4;
  const cx2 = 240+Math.sin(t*0.2)*80, cy2 = 120+Math.cos(t*0.25)*60;
  const d2 = Math.sqrt((dx-cx2)**2 + (dy-cy2)**2), a2 = Math.atan2(dy-cy2, dx-cx2);
  const sp2 = (Math.sin(d2*0.06+a2*2-t*0.9) + Math.cos(d2*0.045-a2*5+t*1.4))*0.3;
  let minD = 999, secD = 999;
  for (const [sX, sY] of src) {
    const dd = Math.sqrt((dx-sX)**2 + (dy-sY)**2);
    if (dd < minD) { secD = minD; minD = dd; } else if (dd < secD) secD = dd;
  }
  const vor = Math.sin((secD-minD)*0.15 + t)*0.25;
  const cell = Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15) + Math.sin((dx+dy)*0.1+t)*0.5 + Math.sin(dx*0.08-dy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + sp1 + sp2 + vor)*2.0);
  const blend = reaction*0.7 + cell*0.3, v = blend*0.5+0.5;
  const pal = [[5,12,55],[12,45,95],[18,85,120],[25,140,130],[65,170,120],[160,185,80],[210,175,60],[220,130,55],[190,75,65],[130,40,70],[70,20,65],[30,12,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction) > 0.65 ? 1.12 : 1.0;
  const glow = Math.max(0, reaction) * 0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*255)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*180)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*80)|0)
  ];
}
